import java.util.*;

public class MaxFlowSolver {
    static class FlowEdge {
        int to, capacity, flow, rev;
        FlowEdge() {}
        FlowEdge(int t, int c, int f, int r) {
            this.to = t;
            this.capacity = c;
            this.flow = f;
            this.rev = r;
        }
    }

    static final int MAXN = 121;
    static List<FlowEdge>[] adj = new ArrayList[MAXN];
    static int[] level = new int[MAXN];
    static int[] ptr = new int[MAXN];
    static int s, t, n;
    static Queue<Integer> q = new LinkedList<>();

    static {
        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static void addEdge(int v, int u, int cap) {
        adj[v].add(new FlowEdge(u, cap, 0, adj[u].size()));
        adj[u].add(new FlowEdge(v, 0, 0, adj[v].size() - 1));
    }

    static boolean buildLevelGraph() {
        Arrays.fill(level, -1);
        level[s] = 0;
        q.clear();
        q.offer(s);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (FlowEdge e : adj[v]) {
                if (level[e.to] < 0 && e.capacity - e.flow > 0) {
                    level[e.to] = level[v] + 1;
                    q.offer(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    static int sendFlow(int v, int flow) {
        if (v == t) return flow;
        for (int i = ptr[v]; i < adj[v].size(); i++) {
            FlowEdge e = adj[v].get(i);
            if (level[e.to] == level[v] + 1 && e.capacity - e.flow > 0) {
                int pushed = sendFlow(e.to, Math.min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    adj[e.to].get(e.rev).flow -= pushed;
                    return pushed;
                }
            }
            ptr[v]++;
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0;
        while (buildLevelGraph()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = sendFlow(s, Integer.MAX_VALUE)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int size = sc.nextInt();
        int tbad = sc.nextInt();

        char[][] maze = new char[size][size];
        char[][] maze_b = new char[size][size];

        int px = -1, py = -1;

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                maze[i][j] = sc.next().charAt(0);
                if (maze[i][j] == 'Z') {
                    px = i;
                    py = j;
                }
            }
        }

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                maze_b[i][j] = sc.next().charAt(0);
            }
        }

        s = 0;
        t = 2 * size * size + 1;

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                int u = i * size + j + 1;
                if (maze[i][j] != '0') {
                    addEdge(s, u, maze[i][j] - '0');
                }
                if (maze_b[i][j] != '0') {
                    addEdge(u + size * size, t, maze_b[i][j] - '0');
                }
            }
        }

        System.out.println(maxFlow());
        sc.close();
    }
}
